// Types for src/data/basemap.json, generated by data_pipeline/build_basemap.py.
// Coordinates are kilometres on a local projection: x = east, y = north.
import basemapJson from "@/data/basemap.json";

/** Flat ring: [x0, y0, x1, y1, ...] */
export type Ring = number[];
/** Outer ring followed by holes */
export type Polygon = Ring[];

export interface County {
  name: string;
  geoid: string;
  rings: Polygon[];
  label: { x: number; y: number };
}

export interface City {
  name: string;
  county: string;
  facilities: number;
  lat: number;
  lon: number;
  x: number;
  y: number;
}

export type LabelKind = "water" | "bay" | "state" | "neighbor";

export interface MapLabel {
  text: string;
  kind: LabelKind;
  x: number;
  y: number;
}

export interface Basemap {
  units: "km";
  frame: { width: number; height: number };
  wisconsin: Polygon[];
  neighbors: Polygon[];
  lakes: Polygon[];
  rivers: Ring[];
  counties: County[];
  /** Flat [x, y, size, kind, ...]; kind 0 = oak, 1 = birch */
  trees: number[];
  cities: City[];
  labels: MapLabel[];
  source: string;
}

export const basemap = basemapJson as Basemap;
